#include <linux/fb.h>
#include <linux/uaccess.h>

int handle_ioctl(unsigned long cmd, unsigned long arg, struct fb_info *info, int type, int fb_depth, unsigned long fb_size) {
    int ret = 0;

    switch (cmd) {
        case FBIOGTYPE: {
            struct fbtype __user *fbt = (struct fbtype __user *)arg;
            struct fbtype local_fbt;

            local_fbt.fb_type = type;
            local_fbt.fb_depth = fb_depth;
            local_fbt.fb_size = fb_size;

            if (copy_to_user(fbt, &local_fbt, sizeof(local_fbt)))
                return -EFAULT;
            break;
        }
        case FBIOPUTCMAP_SPARC:
        case FBIOGETCMAP_SPARC: {
            struct fb_cmap_user __user *ucmap = (struct fb_cmap_user __user *)arg;
            struct fb_cmap cmap;

            if (get_user(cmap.start, &ucmap->start) ||
                get_user(cmap.len, &ucmap->len) ||
                get_user(cmap.red, &ucmap->red) ||
                get_user(cmap.green, &ucmap->green) ||
                get_user(cmap.blue, &ucmap->blue) ||
                get_user(cmap.transp, &ucmap->transp))
                return -EFAULT;

            if (cmap.len <= 0 || cmap.start + cmap.len > 256)
                return -EINVAL;

            if (cmd == FBIOPUTCMAP_SPARC) {
                if (copy_from_user(info->cmap.red + cmap.start, cmap.red, cmap.len * sizeof(__u16)) ||
                    copy_from_user(info->cmap.green + cmap.start, cmap.green, cmap.len * sizeof(__u16)) ||
                    copy_from_user(info->cmap.blue + cmap.start, cmap.blue, cmap.len * sizeof(__u16)) ||
                    (info->cmap.transp && copy_from_user(info->cmap.transp + cmap.start, cmap.transp, cmap.len * sizeof(__u16))))
                    return -EFAULT;
            } else if (cmd == FBIOGETCMAP_SPARC) {
                if (copy_to_user(cmap.red, info->cmap.red + cmap.start, cmap.len * sizeof(__u16)) ||
                    copy_to_user(cmap.green, info->cmap.green + cmap.start, cmap.len * sizeof(__u16)) ||
                    copy_to_user(cmap.blue, info->cmap.blue + cmap.start, cmap.len * sizeof(__u16)) ||
                    (info->cmap.transp && copy_to_user(cmap.transp, info->cmap.transp + cmap.start, cmap.len * sizeof(__u16))))
                    return -EFAULT;
            }
            break;
        }
        default:
            return -EINVAL;
    }

    return ret;
}

