            struct fb_type *fbt;
            fbt = (struct fb_type *)__get_user_ptr(arg);
            if (!fbt)
                return -EFAULT;

            fbt->type = type;
            fbt->depth = fb_depth;
            fbt->size = fb_size;
            break;
